import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

export function packContext(sections, maxBytes) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 0) {
    throw new Error('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)) throw new Error('sections must be an array');

  const ids = new Set();
  const entries = [];
  // Validate every entry before making any budget decisions.
  for (let index = 0; index < sections.length; index++) {
    if (!Object.hasOwn(sections, index)) throw new Error('sections must be dense');
    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) {
      throw new Error('Each section must be an object');
    }
    const { id, text, priority, required } = section;
    if (typeof id !== 'string' || id.length === 0 || ids.has(id)) {
      throw new Error('Section IDs must be nonempty unique strings');
    }
    if (typeof text !== 'string' || !Number.isSafeInteger(priority) || priority < 0 ||
        typeof required !== 'boolean') {
      throw new Error('Invalid section text, priority, or required flag');
    }
    ids.add(id);
    entries.push({ id, text, priority, required, index });
  }

  for (const entry of entries) {
    entry.frame = '### ' + JSON.stringify(entry.id) + '\n' + entry.text + '\n';
    entry.cost = Buffer.byteLength(entry.frame, 'utf8');
  }
  let remaining = maxBytes;
  const frames = [];
  const included = [];
  const selected = new Set();
  const include = entry => {
    remaining -= entry.cost;
    frames.push(entry.frame);
    included.push(entry.id);
    selected.add(entry.id);
  };
  // Subtract instead of summing costs beyond the safe-integer boundary.
  for (const entry of entries) {
    if (!entry.required) continue;
    if (entry.cost > remaining) throw new Error('Required sections exceed maxBytes');
    include(entry);
  }
  const optional = entries.filter(entry => !entry.required);
  optional.sort((a, b) => b.priority - a.priority || a.index - b.index);
  for (const entry of optional) {
    if (entry.cost <= remaining) include(entry);
  }
  const text = frames.join('');
  return {
    text,
    bytes: Buffer.byteLength(text, 'utf8'),
    included,
    omitted: entries.filter(entry => !entry.required && !selected.has(entry.id))
      .map(entry => entry.id)
  };
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  try {
    if (process.argv.length !== 3) throw new Error('Usage: node context-packet.js INPUT_JSON_FILE');
    const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    const result = packContext(input.sections, input.maxBytes);
    process.stdout.write(JSON.stringify(result) + '\n');
  } catch (error) {
    process.stderr.write((error instanceof Error ? error.message : String(error)) + '\n');
    process.exitCode = 2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { packContext } from '../context-packet.js';

const section = (id, text = '', priority = 0, required = false) => ({ id, text, priority, required });
const frame = s => '### ' + JSON.stringify(s.id) + '\n' + s.text + '\n';
const cost = s => Buffer.byteLength(frame(s), 'utf8');

test('safe-integer boundaries and full field validation at zero budget', () => {
  for (const value of [-1, 0.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1, '0', null, undefined, true, 0n]) {
    assert.throws(() => packContext([], value), Error);
    assert.throws(() => packContext([{ ...section('x'), priority: value }], 0), Error);
  }
  assert.deepEqual(packContext([], Number.MAX_SAFE_INTEGER), { text: '', bytes: 0, included: [], omitted: [] });
  assert.deepEqual(packContext([section('x', '', Number.MAX_SAFE_INTEGER)], Number.MAX_SAFE_INTEGER).included, ['x']);
  for (const value of [null, {}, 'x', 1]) assert.throws(() => packContext(value, 0), Error);
  for (const value of [null, [], 1, 'x', undefined]) assert.throws(() => packContext([value], 0), Error);
  for (const key of ['id', 'text', 'priority', 'required']) {
    const missing = section('x');
    delete missing[key];
    assert.throws(() => packContext([missing], 0), Error);
    assert.throws(() => packContext([{ ...section('x'), [key]: undefined }], 0), Error);
  }
  for (const bad of [{ id: '' }, { id: 1 }, { text: null }, { text: 1 }, { required: 0 }, { required: 'false' }]) {
    assert.throws(() => packContext([{ ...section('x'), ...bad }], 0), Error);
  }
  assert.throws(() => packContext([section('x'), section('x')], 0), Error);
  const sparse = new Array(1);
  Object.setPrototypeOf(sparse, { 0: section('inherited') });
  assert.throws(() => packContext(sparse, 0), Error);
});

test('required ordering, priority ties, continued packing, and omission input order', () => {
  const input = [section('low', 'L', 0), section('r1', '', 0, true),
    section('huge', 'x'.repeat(100), 100), section('a', '', 7),
    section('r2', '', 999, true), section('b', '', 7), section('medium', 'x'.repeat(100), 8)];
  const chosen = [input[1], input[4], input[3], input[5]];
  const budget = chosen.reduce((sum, s) => sum + cost(s), 0);
  const expectedText = chosen.map(frame).join('');
  const before = JSON.stringify(input);
  input.forEach(Object.freeze);
  Object.freeze(input);
  assert.deepEqual(packContext(input, budget), { text: expectedText, bytes: budget,
    included: ['r1', 'r2', 'a', 'b'], omitted: ['low', 'huge', 'medium'] });
  assert.equal(JSON.stringify(input), before);
  assert.throws(() => packContext(input, cost(input[1]) + cost(input[4]) - 1), Error);
});

test('exact framing preserves special IDs, Unicode, empty text, and whitespace', () => {
  const ids = ['__proto__', 'constructor', 'A', 'a', ' ', '\n\u0000"\\雪', '\ud800'];
  const input = ids.map((id, i) => section(id, i ? ' é😀\r\n\u0000\ud800 ' : '', 0, true));
  const text = input.map(frame).join('');
  const bytes = Buffer.byteLength(text);
  assert.deepEqual(packContext(input, bytes), { text, bytes, included: ids, omitted: [] });
  assert.throws(() => packContext(input, bytes - 1), Error);
  const s = section('雪', 'é');
  assert.deepEqual(packContext([s], cost(s) - 1), { text: '', bytes: 0, included: [], omitted: ['雪'] });
});

test('CLI stdout, stderr, exit codes, and import isolation', () => {
  const dir = mkdtempSync(join(tmpdir(), 'context-packet-'));
  const cli = fileURLToPath(new URL('../context-packet.js', import.meta.url));
  const run = args => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });
  const failure = result => {
    assert.equal(result.error, undefined);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length > 0);
  };
  try {
    const path = join(dir, 'input.json');
    const input = { sections: [section('雪', 'é', 1, true)], maxBytes: 100, extra: true };
    writeFileSync(path, JSON.stringify(input));
    const result = run([path]);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, JSON.stringify(packContext(input.sections, input.maxBytes)) + '\n');
    failure(run([]));
    failure(run([path, path]));
    failure(run([join(dir, 'missing.json')]));
    for (const contents of ['{', 'null', '[]', '{}',
      JSON.stringify({ sections: [section('r', '', 0, true)], maxBytes: 0 }),
      JSON.stringify({ sections: [section('x', '', Number.MAX_SAFE_INTEGER + 1)], maxBytes: 100 })]) {
      writeFileSync(path, contents);
      failure(run([path]));
    }
    const imported = spawnSync(process.execPath, ['--input-type=module', '-e',
      'await import(' + JSON.stringify(new URL('../context-packet.js', import.meta.url).href) + ')'], { encoding: 'utf8' });
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

